// app/composables/useKeranjang.ts
export function useKeranjang() {
  const isi = ref<string[]>([])
  const tambah = (nama: string) => {
    isi.value.push(nama)
  }
  const jumlah = computed(() => isi.value.length)
  return { isi, tambah, jumlah }
}

